import { streamText, generateText as aiGenerateText, type ModelMessage, type Tool } from "ai"
import { randomUUID } from "crypto"
import type { AgentHandle, AgentMessage, LLMEvent, CanUseToolFn } from "./types"
import { resolveProvider } from "./provider"
import { applyMessageNormalization, applyCaching, applyProviderOptions } from "./transform"
import { adapterState, toLLMEvents } from "./llm-events"

function toModelMessages(messages: AgentMessage[]): ModelMessage[] {
  return messages.map((msg) => {
    if (msg.role === "system") {
      return { role: "system" as const, content: msg.content } as ModelMessage
    }
    if (msg.role === "user") {
      const content =
        typeof msg.content === "string"
          ? msg.content
          : msg.content.map((part) => {
              if (part.type === "text") return { type: "text" as const, text: part.text }
              if (part.type === "image") {
                return {
                  type: "image" as const,
                  image: part.image,
                  ...(part.mediaType ? { mediaType: part.mediaType } : {}),
                }
              }
              return part
            })
      return { role: "user" as const, content } as ModelMessage
    }
    if (msg.role === "assistant") {
      const content =
        typeof msg.content === "string"
          ? msg.content
          : msg.content.map((part) => {
              if (part.type === "text") return { type: "text" as const, text: part.text }
              if (part.type === "reasoning") return { type: "reasoning" as const, text: part.text }
              if (part.type === "tool-call") {
                return {
                  type: "tool-call" as const,
                  toolCallId: part.toolCallId,
                  toolName: part.toolName,
                  args: part.args,
                }
              }
              if (part.type === "tool-result") {
                return {
                  type: "tool-result" as const,
                  toolCallId: part.toolCallId,
                  result: part.result,
                }
              }
              return part
            })
      return { role: "assistant" as const, content } as ModelMessage
    }
    return msg as ModelMessage
  })
}

export function createAgent(input: {
  provider: string
  model: string
  apiKey?: string
  baseURL?: string
  isReasoning?: boolean
  tools?: Record<string, Tool>
  systemPrompt?: string
  messages?: AgentMessage[]
  canUseTool?: CanUseToolFn
}): AgentHandle {
  const sessionId = randomUUID()
  const resolved = resolveProvider({
    providerId: input.provider,
    modelId: input.model,
    apiKey: input.apiKey,
    baseURL: input.baseURL,
    isReasoning: input.isReasoning ?? false,
  })

  const pendingMessages: AgentMessage[] = [...(input.messages ?? [])]
  let interruptSignal: AbortController | undefined
  let killed = false

  const asyncIterable: AsyncIterable<LLMEvent> = {
    [Symbol.asyncIterator]() {
      return createStreamIterator()
    },
  }

  async function* createStreamIterator(): AsyncGenerator<LLMEvent> {
    if (killed) return

    const messages = [...pendingMessages]
    const modelMessages = toModelMessages(messages)

    const npm = getNpmFromProvider(input.provider)
    const transformed = applyMessageNormalization(
      modelMessages,
      input.provider,
      input.model,
      npm,
    )

    if (
      input.provider === "anthropic" ||
      input.provider === "google-vertex-anthropic"
    ) {
      applyCaching(transformed, input.provider)
    }

    const providerOpts = applyProviderOptions(
      input.provider,
      input.model,
      npm,
      input.isReasoning ?? false,
      sessionId,
    )

    const mergedProviderOptions: Record<string, unknown> = {
      ...resolved.options,
      ...(Object.keys(providerOpts).length > 0 ? providerOpts : {}),
    }

    interruptSignal = new AbortController()

    const allMessages: ModelMessage[] = input.systemPrompt
      ? [
          { role: "system" as const, content: input.systemPrompt } as ModelMessage,
          ...transformed,
        ]
      : transformed

    const tools = input.tools ?? {}
    const toolNames = Object.keys(tools).length > 0 ? Object.keys(tools) : undefined

    const result = await streamText({
      model: resolved.model as any,
      messages: allMessages,
      tools: Object.keys(tools).length > 0 ? tools : undefined,
      activeTools: toolNames,
      providerOptions: mergedProviderOptions as any,
      abortSignal: interruptSignal.signal,
      onError(error) {
        console.error("[agent-sdk] stream error:", error)
      },
    })

    const state = adapterState()

    for await (const event of result.fullStream) {
      if (killed) return
      const llmEvents = toLLMEvents(state, event)
      for (const llmEvent of llmEvents) {
        yield llmEvent
      }
    }
  }

  return {
    sessionId,
    stream() {
      return asyncIterable
    },
    write(messages: AgentMessage[]) {
      pendingMessages.push(...messages)
    },
    interrupt() {
      interruptSignal?.abort()
    },
    kill() {
      killed = true
      interruptSignal?.abort()
    },
  }
}

export async function generateText(input: {
  provider: string
  model: string
  apiKey?: string
  baseURL?: string
  isReasoning?: boolean
  prompt: string
  instructions?: string
}): Promise<{ text: string; usage: { inputTokens?: number; outputTokens?: number } }> {
  const resolved = resolveProvider({
    providerId: input.provider,
    modelId: input.model,
    apiKey: input.apiKey,
    baseURL: input.baseURL,
    isReasoning: input.isReasoning ?? false,
  })

  const npm = getNpmFromProvider(input.provider)
  const providerOpts = applyProviderOptions(
    input.provider,
    input.model,
    npm,
    input.isReasoning ?? false,
    "generate-text",
  )

  const mergedProviderOptions: Record<string, unknown> = {
    ...resolved.options,
    ...(Object.keys(providerOpts).length > 0 ? providerOpts : {}),
  }

  const result = await aiGenerateText({
    model: resolved.model as any,
    prompt: input.prompt,
    system: input.instructions,
    providerOptions: mergedProviderOptions as any,
  })

  return {
    text: result.text,
    usage: {
      inputTokens: result.usage?.inputTokens ?? undefined,
      outputTokens: result.usage?.outputTokens ?? undefined,
    },
  }
}

function getNpmFromProvider(providerId: string): string {
  switch (providerId) {
    case "anthropic":
      return "@ai-sdk/anthropic"
    case "alibaba-cn":
    case "alibaba":
    case "zhipuai":
    case "alibaba-coding-plan-cn":
      return "@ai-sdk/openai-compatible"
    default:
      return ""
  }
}