import { createAnthropic } from "@ai-sdk/anthropic"
import { createOpenAICompatible } from "@ai-sdk/openai-compatible"
import type { ResolveProviderResult } from "./types"

type ProviderSDK = {
  languageModel: (id: string) => unknown
}

interface ProviderSpec {
  npm: string
  factory: (opts: Record<string, unknown>) => unknown
  baseURL?: string
  envVar: string
  providerOptions?: (modelId: string, isReasoning: boolean) => Record<string, unknown>
}

const BUNDLED_PROVIDERS: Record<string, ProviderSpec> = {
  anthropic: {
    npm: "@ai-sdk/anthropic",
    factory: (opts) => createAnthropic(opts),
    envVar: "ANTHROPIC_API_KEY",
    providerOptions: () => ({
      headers: {
        "anthropic-beta":
          "interleaved-thinking-2025-05-14,fine-grained-tool-streaming-2025-05-14",
      },
    }),
  },
  "alibaba-cn": {
    npm: "@ai-sdk/openai-compatible",
    factory: (opts) =>
      createOpenAICompatible({
        ...opts,
        name: "alibaba-cn",
        baseURL: (opts.baseURL as string | undefined) ?? "https://dashscope.aliyuncs.com/compatible-mode/v1",
      }),
    baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
    envVar: "DASHSCOPE_API_KEY",
    providerOptions: (modelId, isReasoning) => {
      const opts: Record<string, unknown> = {}
      if (isReasoning && !modelId.includes("kimi-k2-thinking")) {
        opts.enable_thinking = true
      }
      return opts
    },
  },
  alibaba: {
    npm: "@ai-sdk/openai-compatible",
    factory: (opts) =>
      createOpenAICompatible({
        ...opts,
        name: "alibaba",
        baseURL: (opts.baseURL as string | undefined) ?? "https://dashscope-intl.aliyuncs.com/compatible-mode/v1",
      }),
    baseURL: "https://dashscope-intl.aliyuncs.com/compatible-mode/v1",
    envVar: "DASHSCOPE_API_KEY",
    providerOptions: (modelId, isReasoning) => {
      const opts: Record<string, unknown> = {}
      if (isReasoning && !modelId.includes("kimi-k2-thinking")) {
        opts.enable_thinking = true
      }
      return opts
    },
  },
  zhipuai: {
    npm: "@ai-sdk/openai-compatible",
    factory: (opts) =>
      createOpenAICompatible({
        ...opts,
        name: "zhipuai",
        baseURL: (opts.baseURL as string | undefined) ?? "https://open.bigmodel.cn/api/paas/v4",
      }),
    baseURL: "https://open.bigmodel.cn/api/paas/v4",
    envVar: "ZHIPU_API_KEY",
    providerOptions: () => ({
      thinking: { type: "enabled", clear_thinking: false },
    }),
  },
  "alibaba-coding-plan-cn": {
    npm: "@ai-sdk/openai-compatible",
    factory: (opts) =>
      createOpenAICompatible({
        ...opts,
        name: "alibaba-coding-plan-cn",
        baseURL: (opts.baseURL as string | undefined) ?? "https://coding.dashscope.aliyuncs.com/v1",
      }),
    baseURL: "https://coding.dashscope.aliyuncs.com/v1",
    envVar: "ALIBABA_CODING_PLAN_API_KEY",
  },
}

export const supportedProviders = Object.keys(BUNDLED_PROVIDERS)

export function resolveProvider(input: {
  providerId: string
  apiKey?: string
  baseURL?: string
  modelId?: string
  isReasoning?: boolean
}): ResolveProviderResult {
  const spec = BUNDLED_PROVIDERS[input.providerId]
  if (!spec) {
    throw new Error(
      `Unknown provider: "${input.providerId}". Supported: ${supportedProviders.join(", ")}`,
    )
  }

  const apiKey = input.apiKey ?? process.env[spec.envVar]
  if (!apiKey) {
    throw new Error(
      `No API key for provider "${input.providerId}". Set ${spec.envVar} env var or pass apiKey.`,
    )
  }

  const opts: Record<string, unknown> = { apiKey }
  const baseURL = input.baseURL ?? spec.baseURL
  if (baseURL) opts.baseURL = baseURL

  const sdk = spec.factory(opts)

  const modelId = input.modelId ?? "default"
  const sdkObj = sdk as ProviderSDK
  const model = sdkObj.languageModel(modelId)

  const providerOpts = spec.providerOptions
    ? spec.providerOptions(modelId, input.isReasoning ?? false)
    : {}

  const sdkOptionKey = resolveSdkOptionKey(spec.npm, input.providerId)
  const options =
    sdkOptionKey && Object.keys(providerOpts).length > 0
      ? { [sdkOptionKey]: providerOpts }
      : providerOpts

  return { sdk, model, options }
}

function resolveSdkOptionKey(npm: string, providerId: string): string | undefined {
  switch (npm) {
    case "@ai-sdk/anthropic":
      return "anthropic"
    case "@ai-sdk/openai-compatible":
      return "openaiCompatible"
  }
  const dotSplit = providerId.split(".")[0]
  return dotSplit !== providerId ? dotSplit : undefined
}