import type { streamText } from "ai"

type StreamResult = Awaited<ReturnType<typeof streamText>>
type AISDKEvent = StreamResult["fullStream"] extends AsyncIterable<infer T> ? T : never

export interface AdapterState {
  step: number
  text: number
  reasoning: number
  currentTextID: string | undefined
  currentReasoningID: string | undefined
  toolNames: Record<string, string>
}

export function adapterState(): AdapterState {
  return {
    step: 0,
    text: 0,
    reasoning: 0,
    currentTextID: undefined,
    currentReasoningID: undefined,
    toolNames: {},
  }
}

function extractUsage(value: unknown): { inputTokens?: number; outputTokens?: number } | undefined {
  if (!value || typeof value !== "object") return undefined
  const item = value as {
    inputTokens?: number
    outputTokens?: number
    totalTokens?: number
    reasoningTokens?: number
    cachedInputTokens?: number
    inputTokenDetails?: { cacheReadTokens?: number; cacheWriteTokens?: number }
    outputTokenDetails?: { reasoningTokens?: number }
  }
  const entries = Object.entries({
    inputTokens: item.inputTokens,
    outputTokens: item.outputTokens,
    totalTokens: item.totalTokens,
    reasoningTokens: item.outputTokenDetails?.reasoningTokens ?? item.reasoningTokens,
    cacheReadInputTokens: item.inputTokenDetails?.cacheReadTokens ?? item.cachedInputTokens,
    cacheWriteInputTokens: item.inputTokenDetails?.cacheWriteTokens,
  }).filter((entry) => entry[1] !== undefined)
  return entries.length === 0 ? undefined : Object.fromEntries(entries) as { inputTokens?: number; outputTokens?: number }
}

function currentTextID(state: AdapterState, id: string | undefined): string {
  state.currentTextID = id ?? state.currentTextID ?? `text-${state.text++}`
  return state.currentTextID
}

function currentReasoningID(state: AdapterState, id: string | undefined): string {
  state.currentReasoningID = id ?? state.currentReasoningID ?? `reasoning-${state.reasoning++}`
  return state.currentReasoningID
}

import type { LLMEvent } from "./types"

export function toLLMEvents(state: AdapterState, event: AISDKEvent): LLMEvent[] {
  switch (event.type) {
    case "start":
      return []

    case "start-step":
      return [{ type: "step_start", index: state.step }]

    case "finish-step":
      const stepIdx = state.step++
      return [
        {
          type: "step_finish",
          reason: event.finishReason ?? "unknown",
          usage: extractUsage(event.usage) ?? { inputTokens: undefined, outputTokens: undefined },
        },
      ]

    case "finish":
      Object.assign(state, adapterState())
      return [
        {
          type: "finish",
          reason: event.finishReason ?? "unknown",
          usage:
            extractUsage(event.totalUsage) ?? { inputTokens: undefined, outputTokens: undefined },
        },
      ]

    case "text-delta":
      return [{ type: "text", delta: event.text }]

    case "reasoning-delta":
      return [{ type: "reasoning", delta: event.text }]

    case "tool-call":
      state.toolNames[event.toolCallId] = event.toolName
      return [{ type: "tool_call", id: event.toolCallId, name: event.toolName, input: event.input }]

    case "tool-result":
      const name = state.toolNames[event.toolCallId] ?? "unknown"
      delete state.toolNames[event.toolCallId]
      return [{ type: "tool_result", id: event.toolCallId, name, result: event.output }]

    case "error":
      const err = event.error instanceof Error ? event.error : new Error(String(event.error))
      return [{ type: "error", error: err }]

    case "abort":
    case "source":
    case "file":
    case "raw":
    case "tool-output-denied":
    case "tool-approval-request":
    case "text-start":
    case "text-end":
    case "reasoning-start":
    case "reasoning-end":
    case "tool-input-start":
    case "tool-input-delta":
    case "tool-input-end":
      return []

    default:
      return []
  }
}