import type { ModelMessage } from "ai"
import type { JSONSchema7 } from "@ai-sdk/provider"

function sanitizeSurrogates(content: string): string {
  return content.replace(
    /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g,
    "\uFFFD",
  )
}

export function applyMessageNormalization(
  msgs: ModelMessage[],
  providerId: string,
  modelId: string,
  npm: string,
): ModelMessage[] {
  msgs = msgs.map((msg) => {
    switch (msg.role) {
      case "system":
        msg.content = sanitizeSurrogates(msg.content)
        return msg
      case "user":
        if (typeof msg.content === "string") {
          msg.content = sanitizeSurrogates(msg.content)
        } else {
          msg.content = msg.content.map((part) => {
            if (part.type === "text") {
              return { ...part, text: sanitizeSurrogates(part.text) }
            }
            return part
          })
        }
        return msg
      case "assistant":
        if (typeof msg.content === "string") {
          msg.content = sanitizeSurrogates(msg.content)
        } else {
          msg.content = msg.content.map((part) => {
            if (part.type === "text" || part.type === "reasoning") {
              return { ...part, text: sanitizeSurrogates(part.text) }
            }
            return part
          })
        }
        return msg
      case "tool":
        if (!Array.isArray(msg.content)) return msg
        msg.content = msg.content.map((content) => {
          if (content.type === "tool-result") {
            if (content.output.type === "text" || content.output.type === "error-text") {
              content.output.value = sanitizeSurrogates(content.output.value)
            }
          }
          return content
        })
        return msg
    }
    return msg
  })

  if (npm === "@ai-sdk/anthropic") {
    msgs = msgs
      .map((msg) => {
        if (typeof msg.content === "string") {
          if (msg.content === "") return undefined
          return msg
        }
        if (!Array.isArray(msg.content)) return msg
        const filtered = msg.content.filter((part) => {
          if (part.type === "text") return part.text !== ""
          if (part.type === "reasoning") {
            const opts = (part as any).providerOptions?.anthropic
            return part.text.trim().length > 0 || opts?.signature != null || opts?.redactedData != null
          }
          return true
        })
        if (filtered.length === 0) return undefined
        return { ...msg, content: filtered }
      })
      .filter((msg): msg is ModelMessage => msg !== undefined && msg.content !== "")
  }

  if (npm === "@ai-sdk/anthropic" || npm === "@ai-sdk/google-vertex/anthropic") {
    msgs = msgs.flatMap((msg) => {
      if (msg.role !== "assistant" || !Array.isArray(msg.content)) return [msg]
      const parts = msg.content
      const first = parts.findIndex((part) => part.type === "tool-call")
      if (first === -1) return [msg]
      if (!parts.slice(first).some((part) => part.type !== "tool-call")) return [msg]
      return [
        { ...msg, content: parts.filter((part) => part.type !== "tool-call") },
        { ...msg, content: parts.filter((part) => part.type === "tool-call") },
      ]
    })
  }

  return msgs
}

export function applyCaching(
  msgs: ModelMessage[],
  providerId: string,
): ModelMessage[] {
  const system = msgs.filter((msg) => msg.role === "system").slice(0, 2)
  const final = msgs.filter((msg) => msg.role !== "system").slice(-2)

  const seen = new Map<ModelMessage, ModelMessage>()
  const unique = [...system, ...final].filter((msg) => {
    if (seen.has(msg)) return false
    seen.set(msg, msg)
    return true
  })

  for (const msg of unique) {
    const useMessageLevel =
      providerId === "anthropic" || providerId.includes("bedrock")

    if (!useMessageLevel && Array.isArray(msg.content) && msg.content.length > 0) {
      const lastContent = msg.content[msg.content.length - 1]
      if (lastContent && typeof lastContent === "object" && "type" in lastContent) {
        const partType = lastContent.type
        if (partType === "tool-approval-request" || partType === "tool-approval-response") {
          continue
        }
        const partAny = lastContent as any
        partAny.providerOptions = {
          ...(partAny.providerOptions ?? {}),
          anthropic: { cacheControl: { type: "ephemeral" } },
          openaiCompatible: { cache_control: { type: "ephemeral" } },
        }
        continue
      }
    }

    const msgAny = msg as any
    msgAny.providerOptions = {
      ...(msgAny.providerOptions ?? {}),
      anthropic: { cacheControl: { type: "ephemeral" } },
      openaiCompatible: { cache_control: { type: "ephemeral" } },
    }
  }

  return msgs
}

export function applyProviderOptions(
  providerId: string,
  modelId: string,
  npm: string,
  isReasoning: boolean,
  sessionId: string,
): Record<string, unknown> {
  const result: Record<string, unknown> = {}

  if (npm === "@ai-sdk/openai-compatible") {
    if (["zai", "zhipuai"].some((id) => providerId.includes(id))) {
      result.thinking = { type: "enabled", clear_thinking: false }
    }
  }

  if (providerId === "alibaba-cn" && isReasoning && npm === "@ai-sdk/openai-compatible") {
    if (!modelId.toLowerCase().includes("kimi-k2-thinking")) {
      result.enable_thinking = true
    }
  }

  if (providerId === "anthropic") {
    result.toolStreaming = false
  }

  return result
}

export function applySchemaTransform(
  providerId: string,
  modelId: string,
  schema: JSONSchema7,
): JSONSchema7 {
  if (providerId === "moonshotai" || modelId.toLowerCase().includes("kimi")) {
    schema = sanitizeMoonshotSchema(schema) as JSONSchema7
  }

  if (providerId === "google" || modelId.includes("gemini")) {
    schema = sanitizeGeminiSchema(schema) as JSONSchema7
  }

  return schema
}

function sanitizeMoonshotSchema(obj: unknown): unknown {
  if (obj === null || typeof obj !== "object") return obj
  if (Array.isArray(obj)) return obj.map(sanitizeMoonshotSchema)
  if ("$ref" in (obj as object) && typeof (obj as Record<string, unknown>).$ref === "string") {
    return { $ref: (obj as Record<string, unknown>).$ref }
  }
  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    result[key] = sanitizeMoonshotSchema(value)
  }
  if (Array.isArray(result.items)) result.items = (result.items as unknown[])[0] ?? {}
  return result
}

function isPlainObject(node: unknown): node is Record<string, unknown> {
  return typeof node === "object" && node !== null && !Array.isArray(node)
}

function hasCombiner(node: unknown): boolean {
  return isPlainObject(node) && (
    Array.isArray(node.anyOf) || Array.isArray(node.oneOf) || Array.isArray(node.allOf)
  )
}

function hasSchemaIntent(node: unknown): boolean {
  if (!isPlainObject(node)) return false
  if (hasCombiner(node)) return true
  return [
    "type", "properties", "items", "prefixItems", "enum", "const",
    "$ref", "additionalProperties", "patternProperties", "required",
    "not", "if", "then", "else",
  ].some((key) => key in node)
}

function sanitizeGeminiSchema(obj: unknown): unknown {
  if (obj === null || typeof obj !== "object") return obj
  if (Array.isArray(obj)) return obj.map(sanitizeGeminiSchema)

  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    if (key === "enum" && Array.isArray(value)) {
      result[key] = value.map((v) => String(v))
      if (result.type === "integer" || result.type === "number") {
        result.type = "string"
      }
    } else if (typeof value === "object" && value !== null) {
      result[key] = sanitizeGeminiSchema(value)
    } else {
      result[key] = value
    }
  }

  if (result.type === "object" && result.properties && Array.isArray(result.required)) {
    result.required = (result.required as string[]).filter(
      (f) => f in (result.properties as Record<string, unknown>),
    )
  }

  if (result.type === "array" && !hasCombiner(result)) {
    if (result.items == null) result.items = {}
    if (isPlainObject(result.items) && !hasCombiner(result.items) && !hasSchemaIntent(result.items)) {
      (result.items as Record<string, unknown>).type = "string"
    }
  }

  if (result.type && result.type !== "object" && !hasCombiner(result)) {
    delete result.properties
    delete result.required
  }

  return result
}